<tr><th class="style_th" style="text-align:center;">SR</th><td class="style_td" style="text-align:center;">+25</td><td class="style_td" style="text-align:center;">+4</td><td class="style_td" style="text-align:center;">+5</td><td class="style_td" style="text-align:center;">+25</td><td class="style_td" style="text-align:center;">1300</td></tr>
